-- The ombudsman register's first records (migration 042), from research of
-- each scheme's official website on 29 Sep 2026: every figure with the page it
-- came from and the text given for it. NOT checked: a person confirms each one
-- against the live page (Complaints -> Ombudsmen) before the system will say a
-- complaint can go there. Where the research found nothing, the field is empty
-- and the record says so; nothing is copied from another scheme.
INSERT INTO ombudsmen (key, name, website, refer_url, phone, email, post, wait_weeks,
  after_final_response, after_missed_deadline, time_limit_months, time_limit_from,
  who_can_complain, representative, what_to_include, notes, evidence) VALUES
('energy_ombudsman', 'Energy Ombudsman', 'https://www.energyombudsman.org/', 'https://www.energyombudsman.org/raise-dispute', '0330 440 1624', NULL, NULL, 8, true, false, 12, 'final_response', 'Household customers. Since 19 December 2024 also small businesses: fewer than 50 employees and turnover of at most £6.5m (or balance sheet of at most £5m), or yearly use of at most 200,000 kWh electricity or 500,000 kWh gas. Microbusinesses were covered before that.', 'You can be represented or helped by a third party at any stage. What written authority they ask a representative for was not found: check before referring for a landlord or client.', ARRAY['The supplier’s name, the account holder’s name and the account number','The date the complaint was first raised with the supplier','The deadlock (final decision) letter, if one was sent','Copies of emails and letters with the supplier; phone calls with dates, times and names','Evidence of the problem: bills, statements, meter readings']::text[], 'The supplier has 8 weeks to resolve it, unless it sends a deadlock letter sooner. Refer within 12 months of the deadlock letter. Evidence can be uploaded for up to 14 days after the case is made.', '{"wait_weeks": {"url": "https://www.energyombudsman.org/our-process", "text": "Your supplier has 8 weeks to resolve your dispute. If you receive a \"final decision\" or \"deadlock\" letter, or 8 weeks have passed and your complaint hasn''t been resolved, then you can register your dispute with the Energy Ombudsman for free."}, "time_limit": {"url": "https://www.energyombudsman.org/faqs", "text": "You must escalate your dispute within 12 months of receiving the deadlock letter."}, "who_can_complain": {"url": "https://www.energyombudsman.org/news/energy-ombudsman-extends-access-to-small-businesses", "text": "As of 19th December 2024 a ''Small Business Consumer'' is defined as one with: fewer than 50 employees or their full-time equivalent AND an annual turnover of at most £6.5 million OR a balance sheet total of £5.0 million; or an annual consumption of electricity of not more than 200,000 kWh; or an annual consumption of gas of not more than 500,000 kWh."}, "representative": {"url": "https://www.energyombudsman.org/advice-for-consumers/can-my-business-get-help-from-energy-ombudsman", "text": "You are, however, entitled to seek independent advice or be represented or helped by a third party at any stage of the process."}, "what_to_include": {"url": "https://www.energyombudsman.org/additional-support/creating-a-case-with-the-energy-ombudsman", "text": "Information such as your energy supplier''s name, the name of the account holder, the account number and the date you first raised your complaint to the energy supplier will speed up this process. Any evidence of the contact you''ve had with the supplier, such as copies of emails or letters, details of phone calls ... bills, bank statements."}, "phone": {"url": "https://www.energyombudsman.org/additional-support/creating-a-case-with-the-energy-ombudsman", "text": "If you need assistance accessing the online platform, you can call their team on 0330 440 1624 for energy complaints."}}'::jsonb),
('housing_ombudsman', 'Housing Ombudsman', 'https://www.housing-ombudsman.org.uk/', 'https://www.housing-ombudsman.org.uk/residents/bring-your-complaint-to-the-housing-ombudsman/', '0300 111 3000', NULL, 'Housing Ombudsman Service, PO Box 1484, Unit D, Preston PR2 0ET', NULL, true, false, 12, 'final_response', 'Residents of a member landlord (social landlords, including a council AS landlord, and housing associations): tenants, former tenants, leaseholders, shared owners, licensees. Not freeholders. Private landlords only if they joined the scheme voluntarily.', 'A representative needs the Housing Ombudsman’s own consent form, signed by both (section 2), saying the resident agrees to a complaint to the Housing Ombudsman (general consent to act is not enough). One representative per case. Nothing is discussed with anyone else until it arrives.', ARRAY['A copy of the complaint made to the landlord','The landlord’s Stage 2 (final) response','Evidence: repair requests, diary sheets, the landlord’s replies (copies, not originals)','The signed Housing Ombudsman consent form, when complaining for a resident']::text[], 'It investigates only after the landlord’s Stage 2 response. If the landlord misses its deadlines, its Dispute Support team can step in (contact the landlord, issue an order or a Complaint Handling Failure Notice): that is not a referral for investigation. Since 13 January 2026 new complaints are taken by the online form or phone only, not email (casework@housing-ombudsman.org.uk is for existing cases). Complaints about a council as landlord go here, not to the Local Government Ombudsman.', '{"after_final_response": {"url": "https://www.housing-ombudsman.org.uk/residents/waiting-for-a-final-response/", "text": "We can only consider a complaint for investigation once the landlord has provided a stage 2 response; this is sometimes referred to as a ''final response''."}, "time_limit": {"url": "https://www.housing-ombudsman.org.uk/residents/when-to-get-help-from-the-housing-ombudsman/", "text": "You have 12 months from your landlord''s stage 2 response to refer your complaint to us. We are unlikely to investigate complaints you refer after this deadline, unless you have good reasons for the delay."}, "refer_url": {"url": "https://www.housing-ombudsman.org.uk/contact-us/", "text": "From 13 January 2026, the Housing Ombudsman Service only accepts new complaints through their online complaint form or by phone, and email submissions are no longer accepted."}, "representative": {"url": "https://www.housing-ombudsman.org.uk/residents/bringing-a-complaint-to-us-for-somebody-else/", "text": "The consent form must clearly state that the resident agrees to bring a complaint to the Housing Ombudsman Service, not just general consent for your agency to act on their behalf. Both parties must sign section 2 of the consent form."}, "who_can_complain": {"url": "https://www.housing-ombudsman.org.uk/residents/who-can-use-the-ombudsman/", "text": "You can bring a complaint to the Housing Ombudsman if you are or have been in a landlord and tenant relationship with a landlord that is a member of the Scheme. ... The only category of homeowners who are not eligible ... are those who own the freehold of their home."}}'::jsonb),
('lgsco', 'Local Government and Social Care Ombudsman', 'https://www.lgo.org.uk/', 'https://www.lgo.org.uk/how-to-complain', '0300 061 0614', NULL, 'Local Government and Social Care Ombudsman, PO Box 4771, Coventry CV4 0EH', 16, true, false, 12, 'raised', 'Members of the public who have been caused injustice by the matter, or someone authorised to complain for them. Not public bodies. Whether a company (or Greenco acting for a landlord as a business) can complain was NOT confirmed: check before referring.', 'A representative usually needs the person’s written consent on the Ombudsman’s OWN consent form (covering the complaint and sharing their data). Legal authority (power of attorney, deputy, appointee) can stand in for consent.', ARRAY['Confirmation it has been through all of the council’s complaints procedure','A copy of the council’s final response (they may ask for it)','The signed LGSCO consent form, when complaining for someone else']::text[], 'The council must have had a reasonable chance to respond: all stages of its procedure, or no full response within (usually) 16 weeks. Earlier than that the complaint is "premature" and sent back. The 12 months run from when the person BECAME AWARE of the problem, which may be before the complaint was made: the refer-by date here counts from the complaint, so refer well within it. A complaint about a council as LANDLORD (its tenants or leaseholders) goes to the Housing Ombudsman instead. No email address is given for new complaints.', '{"wait_weeks": {"url": "https://www.lgo.org.uk/information-centre/staff-guidance/guidance-on-jurisdiction?chapter=6", "text": "It is usually reasonable to allow up to 16 weeks for a full response to the complaint."}, "time_limit": {"url": "https://www.lgo.org.uk/information-centre/staff-guidance/guidance-on-jurisdiction?chapter=6", "text": "people must bring complaints to the Ombudsman within 12 months of becoming aware of the matter unless there is a good reason for the delay."}, "representative": {"url": "https://www.lgo.org.uk/assets/attach/2288/Complaint-and-consent-form-October-23.pdf", "text": "If you''re complaining on someone else''s behalf they must sign the attached consent form. The LGSCO uses only their own consent form."}, "who_can_complain": {"url": "https://www.lgo.org.uk/information-centre/staff-guidance/guidance-on-jurisdiction?chapter=5", "text": "Complaints by members of the public are still valid if they can show they (or those they are authorised to complain on behalf of) have ''sustained injustice in consequence of the matter''."}, "housing": {"url": "https://www.lgo.org.uk/make-a-complaint/fact-sheets/housing/which-ombudsman-for-complaints-about-social-housing", "text": "The Housing Ombudsman is responsible for all complaints about social housing, including complaints about a local authority''s (or Arms Length Management Organisation''s) relationship as landlord to its tenants or leaseholders."}}'::jsonb),
('tpo', 'The Property Ombudsman', 'https://www.tpos.co.uk/', 'https://www.tpos.co.uk/consumers/make-a-complaint/', '01722 333306', 'admin@tpos.co.uk', 'The Property Ombudsman, Milford House, 43-55 Milford Street, Salisbury, Wiltshire SP1 2BP', 8, true, false, 12, 'final_response', 'Sellers (including small businesses, charities and trusts), buyers, landlords, leaseholders, lessees and tenants, and anyone a complaint is made on behalf of. The complaint to the firm must have been made within 12 months of the problem (or of becoming aware of it).', 'An authorised person complaining for someone must provide a Letter of Authority (their written authority).', ARRAY['The formal complaint sent to the agent (copy)','The agent’s final response / final viewpoint (deadlock) letter, or its last reply if none','All other correspondence with the agent','Evidence relied on, especially of financial loss (copies, not originals)','What went wrong and the outcome wanted, as specifically as possible']::text[], 'Whether a service charge is fair or the quality of the works it pays for is NOT for TPO: that goes to the First-tier Tribunal (Property Chamber). TPO can consider whether the agent acted fairly and reasonably. It usually takes 25 to 30 working days to decide whether to accept a complaint. Check the agent is a TPO member (it must say which scheme it belongs to). The email and postal address came from searches that may have echoed them back: confirm them on the contact page.', '{"wait_weeks": {"url": "https://www.tpos.co.uk/consumers/how-it-works/", "text": "You have complained to the property business and received their final response (their ''final viewpoint'' letter) or more than eight weeks has passed since you made your first complaint."}, "time_limit": {"url": "https://www.tpos.co.uk/complaint-form/", "text": "Your complaint must be received by TPO within 12 months of the date of the agent''s final viewpoint letter."}, "representative": {"url": "https://www.tpos.co.uk/images/documents/forms/TPOE74-RLM_Complaints_Form.pdf", "text": "If you are an Authorised Person you will be required to provide a Letter of Authority to allow TPO to consider the complaint."}, "who_can_complain": {"url": "https://www.tpos.co.uk/images/documents/guidance/TPOE31-6_The_Property_Ombudsman_Scheme_Terms_of_Reference_A4_-_effective_June_2022.pdf", "text": "\"Complainant\" means a seller, including any small business, charity or trust, or buyer or potential seller or potential buyer or landlord or leaseholder or lessee or tenant of property by whom or on whose behalf a complaint is made to the Ombudsman."}, "service_charges": {"url": "https://www.tpos.co.uk/images/documents/guidance/TPOE92_RLM_Consumer_Guide_A4.pdf", "text": "Investigating the fairness of service charges, and the quality of services or works they are collected for, falls outside of the jurisdiction of The Property Ombudsman. Challenges must be referred to the First-Tier Tribunal."}}'::jsonb),
('prs', 'Property Redress Scheme', 'https://www.theprs.co.uk/', 'https://www.theprs.co.uk/Complain', '0333 321 9418', 'info@theprs.co.uk', NULL, NULL, true, false, NULL, NULL, NULL, NULL, '{}'::text[], 'Research could NOT find the Property Redress Scheme’s own rules: how long to wait, the time limit, who can complain, what authority a representative needs, or what to include. Read its Terms of Reference (https://www.theprs.co.uk/terms-of-reference) and Conditions of Complaints before relying on this record, and fill them in. Its process is an initial assessment, then mediation, then adjudication. Letting and property management agents must by law belong to a redress scheme, and must say which one.', '{"refer_url": {"url": "https://www.theprs.co.uk/Complain", "text": "Their online platform and streamlined process allows users to easily submit complaints, track progress, and resolve issues."}, "after_final_response": {"url": "http://www.theprs.co.uk/consumer/how-it-works", "text": "If the agent does not provide a satisfactory response to any complaint, you can refer the complaint to their redress scheme."}}'::jsonb),
('ccw', 'Consumer Council for Water (CCW)', 'https://www.ccw.org.uk/', 'https://www.ccw.org.uk/advice-and-support/make-a-complaint/', '0300 034 2222 (England), 0300 034 3333 (Wales)', NULL, 'CCW, 23 Stephenson Street, Birmingham, B2 4BH', 8, true, false, NULL, NULL, 'Household and business customers of water companies and retailers in England and Wales.', 'If someone is acting for the customer, CCW will usually need the customer’s permission first. What form that permission must take was not found.', ARRAY['The company’s final response letter (or its verbal confirmation)','Evidence: emails, bills, notes of calls','The account details, key dates and the outcome wanted']::text[], 'Complain to the water company first (Stage 1 then Stage 2, 10 working days each), then CCW with the final response or after 8 weeks without one. No time limit for going to CCW was found. WATRS no longer exists: CCW took the next step (mediation and adjudication) in-house in December 2023. CCW’s board minutes say Defra told it to stop adjudication, and it took no new adjudication cases from 21 April 2026; what replaces it was not found. CCW does not handle private disputes such as those with a landlord. Complaint emails to CCW are not actioned: use the form or phone.', '{"wait_weeks": {"url": "https://www.ccw.org.uk/advice-and-support/make-a-complaint/alternative-dispute-resolution/", "text": "you can contact CCW if you''ve completed the company''s complaints process and have received a final response letter or verbal confirmation, or if the company hasn''t responded within eight weeks"}, "representative": {"url": "https://www.ccw.org.uk/advice-and-support/make-a-complaint/complaints-we-can-help-with/", "text": "If someone is acting on your behalf, we will usually need your permission before discussing your complaint with them."}, "watrs": {"url": "https://www.ccw.org.uk/news/changes-make-it-quicker-and-easier-for-water-customers-to-resolve-complaints/", "text": "Customers will no longer have to go to a separate adjudicator (WATRS) if a resolution cannot be found at an earlier stage. Mediation and final adjudication of a dispute will be managed by CCW, with independent support from the Dispute Resolution Ombudsman (DRO)."}, "adr_stopped": {"url": "http://www.ccw.org.uk/aboutus/our-team/board/meetings/", "text": "CCW had been formally instructed by Defra to cease ADR adjudication activities late on 20 April 2026 and had stopped taking new ADR cases the following day."}, "email": {"url": "https://www.ccw.org.uk/contact-us/", "text": "If your email is in relation to a complaint against your water company or retailer, your email to this address will not be actioned."}}'::jsonb),
('fos', 'Financial Ombudsman Service', 'https://www.financial-ombudsman.org.uk/', 'https://www.financial-ombudsman.org.uk/make-complaint', '0800 023 4567 or 0300 123 9123', 'complaint.info@financial-ombudsman.org.uk', 'Financial Ombudsman Service, Exchange Tower, London, E14 9SR', 8, true, false, 6, 'final_response', 'Consumers, micro-enterprises and small businesses (turnover under £6.5m and balance sheet under £5m, for events after 1 April 2019), charities and trusts. For debt collection: the person who has been asked to pay.', 'A representative can be named on the signed complaint form, or given permission verbally or in writing (e.g. an email). A PROFESSIONAL representative needs the customer’s signed declaration form, one per customer. Since 1 April 2025 professional representatives pay £250 a case after 10 free cases a year (£175 back if it is upheld): whether Greenco counts as one is not stated.', ARRAY['Details of the complaint and the dates (e.g. when it happened)','A copy of the business’s final response letter','Authority to act (named on the form, or the signed declaration for a professional representative)']::text[], 'Complain formally to the business first. Refer after its final response, or after 8 weeks without one. The time limit is 6 months from the DATE ON the final response (calendar months); separately, usually within 6 years of the problem or 3 years of becoming aware of it. It only covers a debt collector regulated by the FCA for that activity: check the FCA register.', '{"wait_weeks": {"url": "https://www.financial-ombudsman.org.uk/consumers/complaints-can-help/credit-borrowing-money/debt-collecting", "text": "Before bringing your complaint to us, you should make a formal complaint to the company involved. If they don''t send you a final response letter within eight weeks – or you''re unhappy with their response – you can bring the complaint to us."}, "time_limit": {"url": "https://www.financial-ombudsman.org.uk/consumers/complaints-can-help/expect/time-limits", "text": "You have 6 months from the date on the final response you receive from the financial business to bring your complaint to us."}, "representative": {"url": "https://www.financial-ombudsman.org.uk/consumers/how-to-complain/information-professional-representatives", "text": "When submitting a complaint through a professional representative, you will need to have a copy of the customer''s signed declaration form. You will need to complete the form for each individual customer."}, "charges": {"url": "https://www.financial-ombudsman.org.uk/news/charges-professional-representatives-refer-cases-come-force-today", "text": "professional representatives are charged £250 to refer a case... can refer ten cases for free... £175 back in credit if the complaint is found in favour of the consumer"}, "what_to_include": {"url": "https://www.financial-ombudsman.org.uk/consumers/how-to-complain", "text": "Details needed include information about the complaint and relevant dates involved... and a copy of the financial business''s final response letter."}}'::jsonb)
ON CONFLICT (key) DO NOTHING;
